// The rename endpoint has a side effect of resetting the flap's lock, so
// never rename while a configured curfew window currently covers this
// device - that would silently drop whatever protection (one-way or a
// fully escalated both-ways lock) is in force. Checked against the curfew
// schedule itself rather than the device's live lock state, since an
// already-escalated full lock no longer reports the live curfew-engaged
// state that a lockingMode-based check would look for.
//
// lock_time/unlock_time are in UTC - compare against the UTC clock fields,
// not local ones, or this fires hours off from the real schedule on a
// device whose system clock is local (confirmed live against real data).
function toMinutes(hhmm) {
    const [h, m] = hhmm.split(':').map(Number);
    return h * 60 + m;
}

const curfews = msg.payload.curfew || [];
const now = new Date();
const nowMinutes = now.getUTCHours() * 60 + now.getUTCMinutes();

const curfewActive = curfews.some(c => {
    if (!c.enabled) return false;
    const lockMinutes = toMinutes(c.lock_time);
    const unlockMinutes = toMinutes(c.unlock_time);
    // Overnight windows (e.g. 20:00-07:00) wrap past midnight.
    return lockMinutes <= unlockMinutes
        ? nowMinutes >= lockMinutes && nowMinutes < unlockMinutes
        : nowMinutes >= lockMinutes || nowMinutes < unlockMinutes;
});

if (curfewActive) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'curfew active - rename skipped' });
    node.warn(`Skipping nightly rename for device ${msg.payload.deviceId} - curfew is currently active`);
    return null;
}

node.status({ fill: 'green', shape: 'dot', text: 'curfew clear - renaming' });
return msg;
